$ErrorActionPreference='Stop';$ProgressPreference='SilentlyContinue';$root='C:\JudasValidation';$base='http://192.168.122.1:8872';$out="$root\M78NativeFunctionalResults";$name='m78-native-final-editor-recipes';try{if(Test-Path "$out\$name.json"){throw 'Preserve existing editor inspection'};$link="$root\Build\judas_editor.dir\Release\judas_editor.tlog\link.command.1.tlog";$compile="$root\Build\judas_editor.dir\Release\judas_editor.tlog\CL.command.1.tlog";$objects=@(Get-ChildItem "$root\Build\judas_editor.dir\Release" -Filter '*.obj'|ForEach-Object {@{path=$_.FullName;bytes=$_.Length;sha256=(Get-FileHash $_.FullName).Hash.ToLower()}});$sources=@(Get-ChildItem "$root\Source\src\editor" -File|Where-Object {$_.Extension -eq '.cpp' -or $_.Extension -eq '.h'}|ForEach-Object {@{path=$_.FullName.Substring(($root+'\Source\').Length);bytes=$_.Length;sha256=(Get-FileHash $_.FullName).Hash.ToLower()}});$linkText=[IO.File]::ReadAllText($link);$compileText=[IO.File]::ReadAllText($compile);@{scope='Read-only retained editor object and exact link/source recipe identity; no compile or source/runtime change';objects=$objects;sources=$sources;linkerText=$linkText;compilerText=$compileText;linkRecipeSHA256=(Get-FileHash $link).Hash.ToLower();compileRecipeSHA256=(Get-FileHash $compile).Hash.ToLower();freeBytes=(Get-PSDrive C).Free}|ConvertTo-Json -Depth 6|Set-Content "$out\$name.json" -Encoding UTF8;Invoke-WebRequest -UseBasicParsing "$base/$name.json" -Method Post -InFile "$out\$name.json"|Out-Null}catch{[string]$_.Exception.Message|Set-Content "$out\$name-error.txt";Invoke-WebRequest -UseBasicParsing "$base/$name-error.txt" -Method Post -InFile "$out\$name-error.txt"|Out-Null;exit 1}
